const STORAGE_KEYS={theme:'bersad_theme',products:'bersad_products',admin:'bersad_admin_token',catalogBg:'bersad_catalog_bg'};
const WHATSAPP='09122135489';
const formatPrice=v=>new Intl.NumberFormat('fa-IR').format(Number(v||0));
const defaultProducts=Array.from({length:50},(_,i)=>{const brands=['Tom Ford','Dior','Creed','Chanel','YSL','Amouage','Bvlgari','Armani'];const b=brands[i%brands.length];return{id:i+1,name:`عطر شماره ${i+1} برساد`,brand:b,sku:`BRS-${String(i+1).padStart(4,'0')}`,price:1800000+(i*95000),image:'./assets/images/product-placeholder.svg',description:'رایحه‌ای ماندگار، متعادل و مناسب استفاده روزمره و رسمی.'};});
function getProducts(){const local=localStorage.getItem(STORAGE_KEYS.products);if(!local){localStorage.setItem(STORAGE_KEYS.products,JSON.stringify(defaultProducts));return defaultProducts;}try{return JSON.parse(local)||defaultProducts}catch{return defaultProducts}}
function saveProducts(items){localStorage.setItem(STORAGE_KEYS.products,JSON.stringify(items));}
function productCard(p){return `<article class="card fade-in"><img loading="lazy" src="${p.image||'./assets/images/product-placeholder.svg'}" alt="${p.name}"><div class="card-body"><h3>${p.name||'-'}</h3><div class="muted">${p.brand||'-'}</div><div class="muted">کد: ${p.sku||'-'}</div><div class="price">${formatPrice(p.price)} تومان</div><a class="btn outline" href="./product.html?id=${encodeURIComponent(p.id)}">مشاهده محصول</a></div></article>`}
function applyTheme(){const t=localStorage.getItem(STORAGE_KEYS.theme)||'dark';document.documentElement.classList.toggle('light',t==='light')}
function toggleTheme(){const t=document.documentElement.classList.contains('light')?'dark':'light';localStorage.setItem(STORAGE_KEYS.theme,t);applyTheme();}
function setupBase(){applyTheme();document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.onclick=toggleTheme);const drawer=document.getElementById('drawer');document.querySelectorAll('[data-open-drawer]').forEach(b=>b.onclick=()=>drawer?.classList.add('show'));document.querySelectorAll('[data-close-drawer]').forEach(b=>b.onclick=()=>drawer?.classList.remove('show'));const bg=localStorage.getItem(STORAGE_KEYS.catalogBg);document.querySelectorAll('[data-catalog-bg]').forEach(el=>{if(bg)el.style.backgroundImage=`linear-gradient(rgba(13,10,20,.78),rgba(13,10,20,.88)),url(${bg})`;});}
function renderFeatured(){const root=document.getElementById('featured-products');if(!root)return;root.innerHTML=getProducts().slice(0,8).map(productCard).join('');}
function renderCatalog(){const root=document.getElementById('catalog-grid');if(!root)return;const products=getProducts();const q=(document.getElementById('search')?.value||'').trim().toLowerCase();const b=(document.getElementById('brandFilter')?.value||'');const filtered=products.filter(p=>`${p.name} ${p.brand} ${p.sku}`.toLowerCase().includes(q)&&(!b||p.brand===b));root.innerHTML=filtered.map(productCard).join('')||'<p>محصولی یافت نشد.</p>';const brandSel=document.getElementById('brandFilter');if(brandSel && !brandSel.dataset.ready){[...new Set(products.map(x=>x.brand))].forEach(br=>brandSel.insertAdjacentHTML('beforeend',`<option value="${br}">${br}</option>`));brandSel.dataset.ready='1';}}
function renderProductPage(){const root=document.getElementById('product-detail');if(!root)return;const id=new URLSearchParams(location.search).get('id');const p=getProducts().find(x=>String(x.id)===String(id));if(!p){root.innerHTML='<p>محصول یافت نشد.</p>';return;}const msg=encodeURIComponent(`سلام، برای سفارش ${p.name} با کد ${p.sku} پیام می‌دهم.`);root.innerHTML=`<div class="product-layout fade-in"><img class="card" src="${p.image||'./assets/images/product-placeholder.svg'}" alt="${p.name}"><div class="card" style="padding:1rem 1.2rem"><h1>${p.name}</h1><p class="muted">برند: ${p.brand}</p><p class="muted">کد: ${p.sku}</p><p class="price">${formatPrice(p.price)} تومان</p><p>${p.description||''}</p><div style="display:flex;gap:.5rem;flex-wrap:wrap"><a class="btn" href="https://wa.me/98${WHATSAPP.slice(1)}?text=${msg}" target="_blank" rel="noopener">سفارش در واتساپ</a><a class="btn outline" href="tel:09124105546">تماس</a></div></div></div>`}
function isAdmin(){return localStorage.getItem(STORAGE_KEYS.admin)==='ok'}
function adminGuard(){if(!location.pathname.includes('/admin/'))return;if(location.pathname.endsWith('/admin/login.html'))return;if(!isAdmin())location.href='./login.html';}
function login(){const u=document.getElementById('username')?.value.trim();const p=document.getElementById('password')?.value;if(u==='admin'&&p==='Bersad@1403'){localStorage.setItem(STORAGE_KEYS.admin,'ok');location.href='./products.html';}else{document.getElementById('loginError').textContent='نام کاربری یا رمز عبور نادرست است.';}}
function logout(){localStorage.removeItem(STORAGE_KEYS.admin);location.href='./login.html';}
function adminProducts(){const table=document.getElementById('admin-products');if(!table)return;table.innerHTML=getProducts().map(p=>`<tr><td>${p.name}</td><td>${p.brand}</td><td>${p.sku}</td><td>${formatPrice(p.price)}</td><td><a class="btn outline" href="./product-edit.html?id=${p.id}">ویرایش</a> <button class="btn outline" data-del="${p.id}">حذف</button></td></tr>`).join('');table.querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{const id=b.dataset.del;const next=getProducts().filter(p=>String(p.id)!==id);saveProducts(next);adminProducts();});}
function readFileAsDataURL(file){return new Promise((res,rej)=>{const fr=new FileReader();fr.onload=()=>res(fr.result);fr.onerror=rej;fr.readAsDataURL(file);});}
async function editProductInit(){const form=document.getElementById('product-form');if(!form)return;const id=new URLSearchParams(location.search).get('id');const products=getProducts();const current=products.find(x=>String(x.id)===String(id));if(current){for(const k of ['name','brand','sku','price','description']){const el=form.querySelector(`[name=${k}]`);if(el)el.value=current[k]??'';}document.getElementById('preview').src=current.image||'../assets/images/product-placeholder.svg';}
form.onsubmit=async(e)=>{e.preventDefault();const fd=new FormData(form);const obj={id:current?.id||Date.now(),name:fd.get('name')||'',brand:fd.get('brand')||'',sku:fd.get('sku')||'',price:Number(fd.get('price')||0),description:fd.get('description')||'',image:current?.image||'../assets/images/product-placeholder.svg'};const imgFile=form.querySelector('[name=image]').files[0];if(imgFile)obj.image=await readFileAsDataURL(imgFile);const next=current?products.map(p=>p.id===current.id?obj:p):[obj,...products];saveProducts(next.slice(0,200));location.href='./products.html';};
const bgForm=document.getElementById('bg-form');if(bgForm)bgForm.onsubmit=async(e)=>{e.preventDefault();const f=bgForm.querySelector('[name=catalogbg]').files[0];if(f)localStorage.setItem(STORAGE_KEYS.catalogBg,await readFileAsDataURL(f));document.getElementById('bgMsg').textContent='ذخیره شد.';};}
window.addEventListener('DOMContentLoaded',()=>{setupBase();adminGuard();renderFeatured();renderCatalog();renderProductPage();adminProducts();editProductInit();document.getElementById('search')?.addEventListener('input',renderCatalog);document.getElementById('brandFilter')?.addEventListener('change',renderCatalog);document.getElementById('loginBtn')?.addEventListener('click',login);document.getElementById('logoutBtn')?.addEventListener('click',logout);});
